// Phase 5 interop test: Node must verify what Dart signs.
//
// The constants below are the SAME vector generated by
// `dart run tool/gen_interop_vector.dart` and asserted in
// mobile/test/signature_service_test.dart. If this script passes and the
// Flutter suite passes, receipts signed on a phone are provably
// verifiable by this backend - no trust required, only bytes.
//
// Run: npm run test:phase5

import assert from 'node:assert/strict';
import { canonicalPayload, verifyReceiptSignature } from '../src/utils/transactionSignature.js';

// ---- the shared vector (do not edit by hand; regenerate both sides) ----
const INTEROP_PUBLIC_KEY =
  'A6EHv/POEL4dcN0Y50vAmWfk1jCbpQ1fHdyGZBJVMbg=';
const INTEROP_SIGNATURE =
  'qHn4v9kRRu1g2hkjDTnUnVXM0GyjlwemUvtA5fiNcCXCovkbrPCPnrMm6favvpK11ywX2tpHdVrnB6c4fo/fBg==';
const INTEROP_CANONICAL =
  '{"v":1,"id":"TX_interop_0001","type":"OFFLINE_PAYMENT",' +
  '"sender":"USER_alice","senderWallet":"WALLET_alice",' +
  '"receiver":"USER_bob","receiverWallet":"WALLET_bob",' +
  '"amountPaise":12550,"nonce":"nonce_interop_1",' +
  '"timestampMs":1768473000123,"description":"Interop vector payment"}';

const fixture = {
  transactionId: 'TX_interop_0001',
  senderId: 'USER_alice',
  receiverId: 'USER_bob',
  senderWalletId: 'WALLET_alice',
  receiverWalletId: 'WALLET_bob',
  amount: 125.5,
  type: 'OFFLINE_PAYMENT',
  status: 'PENDING_SYNC',
  description: 'Interop vector payment',
  nonce: 'nonce_interop_1',
  timestamp: '2026-01-15T10:30:00.123Z',
  senderPublicKey: INTEROP_PUBLIC_KEY,
  signature: INTEROP_SIGNATURE,
};

let failed = false;
function check(name, fn) {
  try {
    fn();
    console.log(`  ok - ${name}`);
  } catch (error) {
    failed = true;
    console.error(`  FAIL - ${name}`);
    console.error(`         ${error.message}`);
  }
}

console.log('Phase 5 signature interop (Dart signs, Node verifies):');

check('canonical payload matches the Dart vector byte-for-byte', () => {
  assert.equal(canonicalPayload(fixture), INTEROP_CANONICAL);
});

check('the Dart-produced signature verifies', () => {
  assert.equal(verifyReceiptSignature(fixture), true);
});

check('a tampered amount breaks the signature', () => {
  assert.equal(verifyReceiptSignature({ ...fixture, amount: 999 }), false);
});

check('a tampered receiver breaks the signature', () => {
  assert.equal(
    verifyReceiptSignature({ ...fixture, receiverId: 'USER_mallory' }),
    false,
  );
});

check('a tampered description breaks the signature', () => {
  assert.equal(
    verifyReceiptSignature({ ...fixture, description: 'actually a loan' }),
    false,
  );
});

check('a receipt signed by a different key fails', () => {
  // Some other (valid-looking) Ed25519 public key.
  const otherKey = Buffer.alloc(32, 7).toString('base64');
  assert.equal(
    verifyReceiptSignature({ ...fixture, senderPublicKey: otherKey }),
    false,
  );
});

check('malformed base64 fails closed instead of throwing', () => {
  assert.equal(
    verifyReceiptSignature({ ...fixture, signature: '!!!not-base64!!!' }),
    false,
  );
});

check('unsigned receipts report null (legacy, not invalid)', () => {
  const { signature, senderPublicKey, ...unsigned } = fixture;
  assert.equal(verifyReceiptSignature(unsigned), null);
});

check('half-signed receipts (key, no signature) are invalid', () => {
  const { signature, ...halfSigned } = fixture;
  assert.equal(verifyReceiptSignature(halfSigned), false);
});

if (failed) {
  console.error('\nPhase 5 interop: FAILED');
  process.exit(1);
}
console.log('\nPhase 5 interop: all checks passed.');
